preConditionHook:
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded once with a full sum on the study's first calculated bar, then
// S += TrueRange - TrueRange[Length] as TWO statements (EL evaluates
// S[1] + in - out left to right; folding to S += in - out rounds differently).
// atrLength != atrLookback re-seeds, as the WFSafe_ wrappers do when a
// walkforward re-optimization changes the length. See AtrProfitTarget.
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
// EL: atrValue[n] reads the atrValue VARIABLE's own history, and a variable
// holds its initial 0 for every bar before the strategy's first evaluated
// one -- so for the first max(nearLag, farLag) evaluated bars one or both
// readings are 0. The history is mirrored here as a zero-seeded ring buffer
// holding lags 0..maxLag, re-seeded if the depth ever changes (see
// AtrAboveAverage / BarRangeAboveStd).
{
    const int maxLag = (int)nearLag > (int)farLag ? (int)nearLag : (int)farLag;
    if (atrHistory.size() != (std::size_t)(maxLag + 1)) {
        atrHistory.assign((std::size_t)(maxLag + 1), 0.0);
        atrCursor = 0;
    }
}
atrHistory[atrCursor] = atr;
atrCursor = (atrCursor + 1) % atrHistory.size();
atrNear = atrHistory[(atrCursor + atrHistory.size() - 1 - (std::size_t)(int)nearLag) % atrHistory.size()];
atrFar = atrHistory[(atrCursor + atrHistory.size() - 1 - (std::size_t)(int)farLag) % atrHistory.size()];
